'use strict';

// Deployment entrypoint only. It runs server.js verbatim (as `node server.js` would) and proxies
// Lambda Function URL events to it over loopback. Nothing in the app itself is changed.

const http = require('http');
const net = require('net');

const PORT = process.env.PORT || 3000;
require('./server.js');

let ready = false;
function waitReady() {
  if (ready) return Promise.resolve();
  return new Promise(function (resolve, reject) {
    const deadline = Date.now() + 10000;
    (function attempt() {
      const s = net.connect(Number(PORT), '127.0.0.1');
      s.once('connect', function () { s.destroy(); ready = true; resolve(); });
      s.once('error', function () {
        s.destroy();
        if (Date.now() > deadline) return reject(new Error('server did not start'));
        setTimeout(attempt, 50);
      });
    })();
  });
}

exports.handler = async function (event) {
  await waitReady();

  const method = (event.requestContext && event.requestContext.http && event.requestContext.http.method) || 'GET';
  const rawPath = event.rawPath || '/';
  const query = event.rawQueryString ? '?' + event.rawQueryString : '';
  const headers = Object.assign({}, event.headers);
  delete headers.host;
  delete headers['content-length'];
  if (event.cookies && event.cookies.length) headers.cookie = event.cookies.join('; ');

  const body = event.body ? Buffer.from(event.body, event.isBase64Encoded ? 'base64' : 'utf8') : null;

  return new Promise(function (resolve, reject) {
    const req = http.request(
      { host: '127.0.0.1', port: Number(PORT), method: method, path: rawPath + query, headers: headers },
      function (res) {
        const chunks = [];
        res.on('data', function (c) { chunks.push(c); });
        res.on('end', function () {
          const out = {};
          const cookies = [];
          for (const [k, v] of Object.entries(res.headers)) {
            if (k.toLowerCase() === 'set-cookie') { cookies.push.apply(cookies, [].concat(v)); continue; }
            out[k] = Array.isArray(v) ? v.join(', ') : v;
          }
          resolve({
            statusCode: res.statusCode,
            headers: out,
            cookies: cookies,
            body: Buffer.concat(chunks).toString('base64'),
            isBase64Encoded: true,
          });
        });
      }
    );
    req.on('error', reject);
    if (body) req.write(body);
    req.end();
  });
};
